<template><AppShell title="积分商城" back><view class="reward-pad"><view class="points-head"><view><text class="muted tiny">可用积分</text><text class="points-number">{{points==null?'—':points}}</text></view><button class="ui-button" @click="open('rewards/points')">积分明细 ›</button></view><view class="reward-nav"><button class="ui-button" @click="go('content/activities')">活动中心 ›</button><button class="ui-button" @click="open('rewards/orders')">我的兑换 ›</button></view><text class="muted tiny">免费积分，兑换活动勋章与实物。积分与等级成长值分开。</text><StateView :loading="loading" :error="error" :count="items.length" title="还没有可兑换商品" description="活动商品上架后会在这里展示" @retry="load" /><view class="reward-grid"><button class="ui-button reward-card" v-for="item in items" :key="item.id" @click="go('rewards/item',{id:item.id})"><image v-if="rewardImage(item.image)" :src="rewardImage(item.image)" mode="aspectFill" /><view v-else class="reward-art">{{item.kind==='BADGE'?'★':'礼'}}</view><view class="reward-copy"><text class="tiny muted">{{item.kind==='BADGE'?'活动勋章':'实物兑换'}}</text><text class="bold reward-title">{{item.title}}</text><text class="reward-cost">{{item.pointsCost}} 积分</text><text class="muted tiny">{{item.stock>0?'剩余 '+item.stock+' 件':'已兑完'}}</text></view></button></view><button v-if="items.length<total" class="ui-button btn outline section" :disabled="loading" @click="more">加载更多</button></view></AppShell></template>
<script setup>
import {ref,watch} from 'vue';import {onShow,onReachBottom} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import StateView from '../../components/StateView.vue';import {request,session,requireLogin,go,toast} from '../../lib/api';import {rewardImage} from '../../lib/rewards';import {useList} from '../../lib/useList'
const points=ref(null),{items,total,loading,error,load,more}=useList('/boost/rewards/goods',()=>({}));function open(path){if(requireLogin())go(path)}
watch(()=>session.token,()=>{points.value=null},{flush:'sync'});onShow(async()=>{load();points.value=null;if(session.token)try{points.value=(await request('/boost/rewards/points')).balance}catch(e){toast(e.message)}});onReachBottom(more)
</script>
<style scoped>.reward-pad{padding:16px}.points-head{display:flex;align-items:center;justify-content:space-between;background:#ffe433;padding:20px;border-radius:14px}.points-number{display:block;font-size:36px;font-weight:800;margin-top:3px}.reward-nav{display:flex;justify-content:space-between;margin:18px 0}.reward-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}.reward-card{background:#fff;border-radius:12px;overflow:hidden;text-align:left;min-width:0}.reward-card image,.reward-art{width:100%;height:140px}.reward-art{display:flex;align-items:center;justify-content:center;background:#fff7cf;font-size:56px;color:#a48110}.reward-copy{padding:12px;display:flex;flex-direction:column;gap:5px}.reward-title{font-size:14px;overflow-wrap:anywhere}.reward-cost{font-size:17px;font-weight:700;color:#8d6100}</style>
